import{_ as t,o as n,c as a,ah as i}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Events","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/activites/evenements.md","filePath":"src/en/guide/activites/evenements.md"}'),s={name:"en/guide/activites/evenements.md"};function r(o,e,l,g,d,c){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h1><p>NextBoxx organizes events, free or paid. Any personal account can sign up for them; the <strong>Events Officer</strong> prepares and follows them.</p><h2 id="signing-up-for-an-event" tabindex="-1">Signing up for an event <a class="header-anchor" href="#signing-up-for-an-event" aria-label="Permalink to &quot;Signing up for an event&quot;">​</a></h2><p><strong>Activities → My events</strong> lists upcoming events and your sign-ups. You can also sign up from the NextBoxx website: your account is then created, or reused, and the <strong>Participant</strong> role is added to your roles. This role gives no access to a training.</p><p>Click <strong>Sign up</strong>. The status of your sign-up tells you where you stand:</p><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Confirmed</strong></td><td>Your place is confirmed</td></tr><tr><td><strong>Awaiting payment</strong></td><td>Your place is reserved until the payment deadline. Without payment, the sign-up is cancelled and the place freed</td></tr><tr><td><strong>Waiting list</strong></td><td>The event is full; you will be notified as soon as a place frees up</td></tr><tr><td><strong>Cancelled</strong></td><td>Cancelled by you, for lack of payment in time, or because the event is cancelled</td></tr></tbody></table><p>A few rules:</p><ul><li><strong>A free event</strong> confirms your sign-up at once, and accepts registrants until it starts.</li><li><strong>A paid event</strong> issues an invoice at sign-up, <strong>to be paid before the deadline</strong>, 48 hours before the start. Full payment confirms the sign-up. Without full payment by that date, the sign-up is cancelled, the invoice cancelled by a credit note, and the place freed. Payment details are in &quot;Payment details&quot;.</li><li><strong>A freed place</strong> (or a raised capacity) goes to the first on the <strong>waiting list</strong>, who is notified, and who receives their invoice if the event is paid.</li><li>Sign-ups are refused if the event is closed or if you are already signed up. A <strong>suspended account</strong> for non-payment cannot sign up for a <strong>paid</strong> event (a free event remains possible). An <strong>organization account</strong> does not sign up: each participant does so with their personal account.</li></ul><h3 id="cancelling-your-sign-up" tabindex="-1">Cancelling your sign-up <a class="header-anchor" href="#cancelling-your-sign-up" aria-label="Permalink to &quot;Cancelling your sign-up&quot;">​</a></h3><p><strong>Cancel my sign-up</strong> frees your place for the next person and cancels an unpaid invoice. You can cancel from the waiting list, while awaiting payment, or a confirmed sign-up on a <strong>free</strong> event. <strong>A place already paid cannot be cancelled</strong> from your space: contact the team.</p><p>If you sign up again afterwards, your cancelled sign-up is taken up again with a new invoice.</p><h2 id="organizing-events" tabindex="-1">Organizing events <a class="header-anchor" href="#organizing-events" aria-label="Permalink to &quot;Organizing events&quot;">​</a></h2><p>The Events Officer and the Administrator manage <strong>Activities → Events</strong>. The list is organized into <strong>Upcoming</strong>, <strong>Past</strong> and <strong>Cancelled</strong>.</p><h3 id="creating-and-publishing" tabindex="-1">Creating and publishing <a class="header-anchor" href="#creating-and-publishing" aria-label="Permalink to &quot;Creating and publishing&quot;">​</a></h3><p><strong>New event</strong>: title, presentation (shown on the NextBoxx website and in Kura), start, end (optional), venue, <strong>places</strong> and <strong>price</strong> in FCFA (0 for free). It is created as a <strong>draft</strong> and takes sign-ups <strong>only once published</strong>.</p><ul><li><strong>Publish</strong> shows it on the website and in Kura.</li><li>Dates are in the future and the end after the start.</li><li>As soon as there is a registrant, <strong>the price no longer changes</strong> and the capacity cannot fall below the places taken. Raising the capacity gives its places to the waiting list.</li><li>Registrants are <strong>not notified</strong> of modifications.</li></ul><h3 id="following-the-registrants" tabindex="-1">Following the registrants <a class="header-anchor" href="#following-the-registrants" aria-label="Permalink to &quot;Following the registrants&quot;">​</a></h3><p>An event&#39;s page shows places taken, the waiting list, the payment deadline, and each registrant with their status, sign-up date and <strong>invoice</strong> (with the balance due). The Officer consults invoices; <strong>the Coordinator records payments</strong> (see <a href="./../coordinateur/facturation.html">Billing</a>). Event invoices enter neither the billing calendar, nor follow-ups, nor the Direction and Reporting dashboards.</p><h3 id="cancelling-an-event" tabindex="-1">Cancelling an event <a class="header-anchor" href="#cancelling-an-event" aria-label="Permalink to &quot;Cancelling an event&quot;">​</a></h3><p><strong>Cancel the event</strong> is possible as long as it has not started, with a <strong>reason given to the registrants</strong>. Each registrant is cancelled and notified; what was paid is refunded by a <strong>credit note</strong>, what remained due is cancelled by a credit note.</p>',20)])])}const p=t(s,[["render",r]]);export{u as __pageData,p as default};
